    ('_athena_farmbot', '\n'),
    ('_athena_farmbot.constants', '"""Game tables copied from the official engine (kaggle-environments 1.32.7).\n\nValues here are verified against ``kaggle_environments/envs/kaggriculture``\nby ``tests/test_constants_parity.py``.\n"""\n\nimport math\n\nCROPS = {\n    "WHEAT": {\n        "seed": 10,\n        "first_yield_day": 2,\n        "max_yield_day": 4,\n        "interval": 0,\n        "max_yield": 6,\n        "ongoing": False,\n    },\n    "CARROT": {\n        "seed": 20,\n        "first_yield_day": 2,\n        "max_yield_day": 3,\n        "interval": 0,\n        "max_yield": 4,\n        "ongoing": False,\n    },\n    "TOMATO": {\n        "seed": 50,\n        "first_yield_day": 8,\n        "max_yield_day": 8,\n        "interval": 1,\n        "max_yield": 4,\n        "ongoing": True,\n    },\n    "STRAWBERRY": {\n        "seed": 100,\n        "first_yield_day": 10,\n        "max_yield_day": 10,\n        "interval": 2,\n        "max_yield": 4,\n        "ongoing": True,\n    },\n    "MELON": {\n        "seed": 80,\n        "first_yield_day": 10,\n        "max_yield_day": 12,\n        "interval": 0,\n        "max_yield": 6,\n        "ongoing": False,\n    },\n}\n\nANIMALS = {\n    "GOOSE": {\n        "cost": 300,\n        "structure": "COOP",\n        "first_yield_day": 4,\n        "interval": 1,\n        "max_held": 4,\n        "product": "EGG",\n    },\n    "COW": {\n        "cost": 400,\n        "structure": "PASTURE",\n        "first_yield_day": 8,\n        "interval": 2,\n        "max_held": 6,\n        "product": "MILK",\n    },\n    "SHEEP": {\n        "cost": 500,\n        "structure": "PASTURE",\n        "first_yield_day": 6,\n        "interval": 3,\n        "max_held": 6,\n        "product": "WOOL",\n    },\n}\n\nPRODUCTS = ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON", "EGG", "MILK", "WOOL", "FERTILIZER"]\nCROP_PRODUCTS = ("WHEAT", "CARROT", "TOMATO", "STRAWBERRY", "MELON")\nANIMAL_PRODUCT = {"GOOSE": "EGG", "COW": "MILK", "SHEEP": "WOOL"}\n\nMARKET_I0 = 10000\nPRICE_FLOOR = 1\nHINGE_GAIN = 8.0\n\nMARKET_PARAMS = {\n    "WHEAT": {\n        "base": 25,\n        "I0": MARKET_I0,\n        "T": 400,\n        "below_func": "sqrt",\n        "below_target": 0.80,\n        "above_func": "log",\n        "above_target": 0.20,\n    },\n    "CARROT": {\n        "base": 35,\n        "I0": MARKET_I0,\n        "T": 450,\n        "below_func": "hinge",\n        "below_target": 1.00,\n        "above_func": "sqrt",\n        "above_target": 0.70,\n    },\n    "TOMATO": {\n        "base": 60,\n        "I0": MARKET_I0,\n        "T": 200,\n        "below_func": "hinge",\n        "below_target": 0.40,\n        "above_func": "sqrt",\n        "above_target": 0.60,\n    },\n    "STRAWBERRY": {\n        "base": 120,\n        "I0": MARKET_I0,\n        "T": 100,\n        "below_func": "sqrt",\n        "below_target": 0.70,\n        "above_func": "linear",\n        "above_target": 1.60,\n    },\n    "MELON": {\n        "base": 250,\n        "I0": MARKET_I0,\n        "T": 300,\n        "below_func": "log",\n        "below_target": 0.20,\n        "above_func": "sq",\n        "above_target": 3.60,\n    },\n    "EGG": {\n        "base": 50,\n        "I0": MARKET_I0,\n        "T": 332,\n        "below_func": "hinge",\n        "below_target": 0.40,\n        "above_func": "log",\n        "above_target": 0.20,\n    },\n    "MILK": {\n        "base": 160,\n        "I0": MARKET_I0,\n        "T": 122,\n        "below_func": "sqrt",\n        "below_target": 0.60,\n        "above_func": "linear",\n        "above_target": 1.60,\n    },\n    "WOOL": {\n        "base": 200,\n        "I0": MARKET_I0,\n        "T": 105,\n        "below_func": "log",\n        "below_target": 0.20,\n        "above_func": "sq",\n        "above_target": 3.20,\n    },\n    "FERTILIZER": {\n        "base": 100,\n        "I0": MARKET_I0,\n        "T": 200,\n        "below_func": "linear",\n        "below_target": 0.40,\n        "above_func": "linear",\n        "above_target": 0.40,\n    },\n}\n\nSHOPS = {\n    "BAKERY": ["EGG", "WHEAT"],\n    "PIZZA_SHOP": ["MILK", "TOMATO", "WHEAT"],\n    "BRUNCH_SPOT": ["EGG", "WHEAT", "STRAWBERRY"],\n    "YARN_STORE": ["WOOL"],\n    "ICE_CREAM_SHOP": ["STRAWBERRY", "MILK", "WHEAT"],\n    "PET_CAFE": ["CARROT"],\n    "SMOOTHIE_SHOP": ["STRAWBERRY", "MILK"],\n    "FARMERS_MARKET": ["WHEAT", "CARROT", "TOMATO", "STRAWBERRY"],\n}\nMAX_SHOP_INSTANCES = 8\n\nLAND_ORDER = ["NE", "SW", "SE"]\nLAND_PRICES = [1000, 2000, 4000]\n\nFARMER_MOVES = {"NORTH": (0, -1), "SOUTH": (0, 1), "EAST": (1, 0), "WEST": (-1, 0)}\n\n\ndef fib_hire_cost(n_already_today, mult=1):\n    """Cost of the next hire when ``n_already_today`` hands were hired today."""\n    a, b = 1, 1\n    for _ in range(n_already_today):\n        a, b = b, a + b\n    return mult * a\n\n\ndef cumulative_hire_cost(count, mult=1):\n    return sum(fib_hire_cost(i, mult) for i in range(count))\n\n\ndef shape(func, x, T=None):\n    x = max(0.0, x)\n    if func == "linear":\n        return x\n    if func == "sq":\n        return x * x\n    if func == "sqrt":\n        return math.sqrt(x)\n    if func == "log":\n        return math.log(1.0 + x)\n    if func == "log10":\n        return math.log10(1.0 + x)\n    if func == "hinge":\n        if not T or T <= 0:\n            return x\n        u = x / T\n        return u + HINGE_GAIN * max(0.0, u - 1.0) ** 2\n    return x\n\n\n_PRICE_CACHE = {}\n\n\ndef market_price(item, inventory, params=None):\n    """Exact copy of the engine\'s price function (rounded, floored at 1). Pure in (item,\n    inventory) for the default market, so memoised: the sale scheduler asks ~2.5 million\n    times a game and this was 75 % of the agent\'s run time."""\n    if params is None:\n        key = (item, inventory)\n        hit = _PRICE_CACHE.get(key)\n        if hit is None:\n            hit = _PRICE_CACHE[key] = _market_price(item, inventory, MARKET_PARAMS)\n        return hit\n    return _market_price(item, inventory, params)\n\n\ndef _market_price(item, inventory, params):\n    p = params[item]\n    base, I0, T = p["base"], p["I0"], p["T"]\n    if inventory < I0:\n        f = p["below_func"]\n        amp = p["below_target"] * base / shape(f, T, T)\n        price = base + amp * shape(f, I0 - inventory, T)\n    else:\n        f = p["above_func"]\n        amp = p["above_target"] * base / shape(f, T, T)\n        price = base - amp * shape(f, inventory - I0, T)\n    return max(PRICE_FLOOR, int(round(price)))\n\n\ndef quadrant_of(x, y, board_size=10):\n    half = board_size // 2\n    return ("N" if y < half else "S") + ("W" if x < half else "E")\n\n\ndef shed_access_tiles(board_size=10):\n    half = board_size // 2\n    return [(half - 1, half - 1), (half, half - 1), (half - 1, half), (half, half)]\n'),
    ('_athena_farmbot.tracker', '"""Market tracker: demand, opponent sales and price projection from the observation.\n\nThe engine\'s market is fully knowable from the observation: the unlocked shops fix the\nconsumption schedule (one unit per product per shop every 4 steps, two for single-product\nshops, plus the town\'s one unit per product per day), the observation carries the market\ninventory, and each unit sold adds one to it (unless it sold at $1) while each unit bought\nremoves one. So between two observations\n\n    inventory[t+1] - inventory[t] = ours_net[t] + opponent_net[t] - consumption[t]\n\nwhere ours_net is our own executed sales minus purchases at step t, which we can\nreproduce from our order list and shed. Everything the opponent sold is therefore\nattributable one step after it happened. Stdlib only; O(products) per step.\n"""\n\nfrom .constants import ANIMALS, CROPS, LAND_PRICES, PRODUCTS, SHOPS, fib_hire_cost, market_price\n\nSHOP_INTERVAL = 4\nCENTER_INTERVAL = 24\nTOWN_CENTER_PRODUCTS = [p for p in PRODUCTS if p != "FERTILIZER"]\nBUYABLE = ("WHEAT", "FERTILIZER")\n\n\ndef consumption(shops, step):\n    """Units removed from the market by the town after the market resolves at `step`."""\n    out = {p: 0 for p in PRODUCTS}\n    if step % SHOP_INTERVAL == 0:\n        for shop in shops:\n            products = SHOPS[shop]\n            mult = 2 if len(products) == 1 else 1\n            for p in products:\n                out[p] += mult\n    if step % CENTER_INTERVAL == 0:\n        for p in TOWN_CENTER_PRODUCTS:\n            out[p] += 1\n    return out\n\n\ndef daily_consumption(shops):\n    """Units per day the town absorbs per product with these shops unlocked."""\n    out = {p: 0 for p in PRODUCTS}\n    for shop in shops:\n        products = SHOPS[shop]\n        mult = 2 if len(products) == 1 else 1\n        for p in products:\n            out[p] += mult * (CENTER_INTERVAL // SHOP_INTERVAL)\n    for p in TOWN_CENTER_PRODUCTS:\n        out[p] += 1\n    return out\n\n\ndef executed_market(\n    orders,\n    shed_after_drops,\n    inventory,\n    money,\n    hires_today=0,\n    quadrants=1,\n    params=None,\n    shed_capacity=100,\n):\n    """Reproduce the engine\'s market for our own order list: atomic orders (HIRE at the\n    Fibonacci cost for the n-th hire today, BUY_LAND at the next quadrant\'s price) are\n    charged first; then each order is processed one unit at a time in list order, sales\n    paying in and purchases paying out as they go. Returns (sold, bought): units that add\n    to / remove from the market inventory (a unit sold at $1 adds nothing)."""\n    stock = dict(shed_after_drops)\n    inv = dict(inventory)\n    cash = float(money)\n    sold, bought = {}, {}\n    n_hired = int(hires_today)\n    land_index = max(0, int(quadrants) - 1)\n    for order in orders or []:\n        if not order:\n            continue\n        if order[0] == "HIRE":\n            cost = fib_hire_cost(n_hired)\n            if cash >= cost:\n                cash -= cost\n                n_hired += 1\n        elif order[0] == "BUY_LAND":\n            if land_index < len(LAND_PRICES) and cash >= LAND_PRICES[land_index]:\n                cash -= LAND_PRICES[land_index]\n                land_index += 1\n    for order in orders or []:\n        if not order or order[0] in ("HIRE", "BUY_LAND") or len(order) < 3:\n            continue\n        op, item = order[0], order[1]\n        try:\n            qty = int(order[2])\n        except (TypeError, ValueError):\n            continue\n        for _ in range(max(0, qty)):\n            if op == "SELL" and item in PRODUCTS:\n                if stock.get(item, 0) <= 0:\n                    break\n                price = market_price(item, inv[item], params)\n                stock[item] -= 1\n                cash += price\n                if price > 1:\n                    inv[item] += 1\n                    sold[item] = sold.get(item, 0) + 1\n            elif op == "BUY_PRODUCT" and item in BUYABLE:\n                price = market_price(item, inv[item] - 1, params)\n                if cash < price or sum(stock.values()) >= shed_capacity:\n                    break\n                cash -= price\n                inv[item] -= 1\n                stock[item] = stock.get(item, 0) + 1  # sellable later in this same list\n                bought[item] = bought.get(item, 0) + 1\n            elif op == "BUY_SEED" and item in CROPS:\n                if cash < CROPS[item]["seed"]:\n                    break\n                cash -= CROPS[item]["seed"]\n            elif op == "BUY_ANIMAL" and item in ANIMALS:\n                if cash < ANIMALS[item]["cost"]:\n                    break\n                cash -= ANIMALS[item]["cost"]\n            else:\n                break\n    return sold, bought\n\n\ndef shed_after_unit_actions(shed, inventories, unit_actions):\n    """Our shed once this step\'s DROP/PLACE/PICKUP resolve (they precede the market)."""\n    stock = dict(shed)\n    for k, action in enumerate(unit_actions):\n        if not action:\n            continue\n        inv = inventories[k] if k < len(inventories) else {}\n        if action[0] == "DROP":\n            for item, qty in inv.items():\n                if item in PRODUCTS:\n                    stock[item] = stock.get(item, 0) + qty\n        elif action[0] == "PLACE" and len(action) >= 2 and action[1] in PRODUCTS:\n            qty = int(action[2]) if len(action) >= 3 else 1\n            stock[action[1]] = stock.get(action[1], 0) + min(qty, inv.get(action[1], 0))\n        elif action[0] == "PICKUP" and len(action) >= 2 and action[1] in PRODUCTS:\n            qty = int(action[2]) if len(action) >= 3 else 1\n            stock[action[1]] = max(0, stock.get(action[1], 0) - qty)\n    return stock\n\n\nclass MarketTracker:\n    """Call ``update(obs, our_previous_action)`` once per step, before acting."""\n\n    def __init__(self):\n        self.prev = (\n            None  # (step, inventory, shops, shed, inventories, money, hires_today, quadrants)\n        )\n        self.opponent_net = {}  # step -> {product: units sold minus bought}\n        self.opponent_daily = {}  # day -> {product: net units}\n        self.consumed = {}  # step -> consumption dict\n        self.last_step = -1\n\n    def update(self, obs, our_previous_action=None):\n        step = int(obs.get("step", obs.get("day", 0) * 24 + obs.get("hour", 0)))\n        if step <= self.last_step:\n            self.__init__()\n        self.last_step = step\n        market = obs.get("market") or {}\n        inventory = dict(market.get("inventory") or {})\n        shops = list((obs.get("town") or {}).get("unlocked_shops") or [])\n        private = obs.get("private") or {}\n        farm = obs["farms"][obs["player"]]\n        shed = dict(private.get("shed") or {})\n        inventories = [dict(i or {}) for i in private.get("inventories") or []]\n        money = float(farm.get("money", 0))\n        if self.prev is not None and inventory:\n            p_step, p_inv, p_shops, p_shed, p_invs, p_money, p_hires, p_quadrants = self.prev\n            if p_step == step - 1 and p_inv:\n                action = our_previous_action or {}\n                units = [action.get("farmer") or ["PASS"]] + list(action.get("hands") or [])\n                stock = shed_after_unit_actions(p_shed, p_invs, units)\n                ours_sold, ours_bought = executed_market(\n                    action.get("market"), stock, p_inv, p_money, p_hires, p_quadrants\n                )\n                used = consumption(p_shops, p_step)\n                net = {}\n                for p in PRODUCTS:\n                    delta = inventory.get(p, p_inv.get(p, 0)) - p_inv.get(p, 0)\n                    net[p] = delta + used[p] - ours_sold.get(p, 0) + ours_bought.get(p, 0)\n                self.opponent_net[p_step] = net\n                self.consumed[p_step] = used\n                day = p_step // 24\n                daily = self.opponent_daily.setdefault(day, {p: 0 for p in PRODUCTS})\n                for p in PRODUCTS:\n                    daily[p] += net[p]\n        self.prev = (\n            step,\n            inventory,\n            shops,\n            shed,\n            inventories,\n            money,\n            int(farm.get("hires_today", 0) or 0),\n            len(farm.get("unlocked_quadrants") or ["NW"]),\n        )\n        return self\n\n    def opponent_sold_today(self, day, product):\n        return self.opponent_daily.get(day, {}).get(product, 0)\n\n    def demand_per_day(self, shops):\n        return daily_consumption(shops)\n\n\n__all__ = ["MarketTracker", "consumption", "daily_consumption", "executed_market"]\n'),
    ('_athena_farmbot.value', '"""Value model: price projection per product per remaining day, and the value of options.\n\nLayers:\n1. Consumption forecast: the unlocked shops\' schedule (deterministic) plus the expected\n   consumption of the shop draws still to come (one every third day, uniform over the\n   eight shop types, eight shops at most).\n2. Opponent supply forecast: their farm is in the observation (every plant with its\n   planting day, every animal), so their future harvests are computable; sales follow\n   production with a short lag. Melons are dumped the day they ripen (every top bot does).\n3. Inventory projection: inventory[d+1] = inventory[d] + ours[d] + theirs[d] - used[d],\n   priced with the engine\'s own curve, giving the marginal price of a unit sold on day d.\n\nOption values read that curve: a sale schedule, a tile planted with a crop, an animal, a\ndose of fertilizer. Stdlib only, O(products x days) per call.\n"""\n\nfrom .constants import ANIMALS, CROPS, PRODUCTS, SHOPS, market_price\nfrom .tracker import daily_consumption\n\nFINAL_DAY = 29\nUNLOCK_DAYS = (3, 6, 9, 12, 15, 18, 21, 24)\nMAX_SHOPS = 8\n# Expected units per harvest for the way the ladder farms (unfertilized wheat/carrots at\n# their last yield day, melons cut when first ripe, ongoing crops with some fertilizer).\nUNITS_PER_HARVEST = {"WHEAT": 4.0, "CARROT": 3.0, "MELON": 5.0, "STRAWBERRY": 1.3, "TOMATO": 1.3}\nANIMAL_UNITS_PER_DAY = {"COW": 1.5, "SHEEP": 1.33, "GOOSE": 2.0}  # fed and cared\nFERTILIZER_SURPLUS = 0.7  # units per animal per day left after the farm\'s own doses\nSALES_LAG = 0.5  # share of a day\'s production sold the next day\n\n\ndef load_fit(path):\n    """Replace the supply constants with the ones fitted by research/fit_forecast.py."""\n    import json\n\n    global FERTILIZER_SURPLUS, SALES_LAG\n    with open(path) as fh:\n        theta = json.load(fh)["theta"]\n    for crop in UNITS_PER_HARVEST:\n        UNITS_PER_HARVEST[crop] = float(theta[crop])\n    for animal in ANIMAL_UNITS_PER_DAY:\n        ANIMAL_UNITS_PER_DAY[animal] = float(theta[animal])\n    FERTILIZER_SURPLUS = float(theta["FERT"])\n    SALES_LAG = float(theta["LAG"])\n\n\nANIMAL_PRODUCT = {a: ANIMALS[a]["product"] for a in ANIMALS}\n\n\ndef remaining_unlocks(shops, day):\n    """Unlock days still ahead that will actually add a shop."""\n    room = MAX_SHOPS - len(shops)\n    ahead = [d for d in UNLOCK_DAYS if d > day]\n    return ahead[: max(0, room)]\n\n\ndef expected_draw_consumption():\n    """Daily consumption one uniformly drawn shop adds, per product."""\n    out = {p: 0.0 for p in PRODUCTS}\n    for products in SHOPS.values():\n        mult = 2 if len(products) == 1 else 1\n        for p in products:\n            out[p] += mult * 6 / len(SHOPS)\n    return out\n\n\ndef consumption_forecast(shops, day, last_day=FINAL_DAY):\n    """{day: {product: units consumed that day}} for day..last_day."""\n    base = daily_consumption(shops)\n    extra = expected_draw_consumption()\n    unlocks = remaining_unlocks(shops, day)\n    out = {}\n    for d in range(day, last_day + 1):\n        n_new = sum(1 for u in unlocks if u <= d)\n        out[d] = {p: base[p] + n_new * extra[p] for p in PRODUCTS}\n    return out\n\n\ndef supply_forecast(farm, day, last_day=FINAL_DAY, melon_dump=True, calendar=False, bonus_share=1.0):\n    """{day: {product: units produced that day}} from a farm\'s visible tiles.\n\n    calendar: animals on their real production calendar instead of a smooth daily rate — a\n    tile shows its placed_day, the units it holds and its pending care bonus, so the nights it\n    produces (placed + first_yield + k x interval) and roughly how much are public. Herds are\n    placed together, so wool and milk reach the market in waves; a smooth flow misreads a\n    saturated town as crashed for good. bonus_share scales the care bonus assumed for future\n    productions (1 = fed and cared every day, 0 = the unfed base unit only)."""\n    out = {d: {p: 0.0 for p in PRODUCTS} for d in range(day, last_day + 1)}\n    n_animals = 0\n    for row in farm.get("tiles") or []:\n        for tile in row:\n            if not isinstance(tile, dict):\n                continue\n            if tile.get("kind") == "PLANT":\n                crop = tile["crop"]\n                data = CROPS[crop]\n                planted = tile.get("planted_day", day)\n                if data["ongoing"]:\n                    first = planted + data["first_yield_day"]\n                    for k in range(data["max_yield"]):\n                        d = first + k * data["interval"]\n                        if day <= d <= last_day:\n                            out[d][crop] += UNITS_PER_HARVEST[crop]\n                else:\n                    if crop == "MELON" and melon_dump:\n                        d = planted + data["first_yield_day"]\n                    else:\n                        d = planted + data["max_yield_day"]\n                    d = max(d, day)\n                    if d <= last_day:\n                        out[d][crop] += UNITS_PER_HARVEST[crop]\n            elif "animal" in tile:\n                n_animals += 1\n                animal = tile["animal"]\n                a = ANIMALS[animal]\n                placed = tile.get("placed_day", day)\n                if calendar:\n                    prod = ANIMAL_PRODUCT[animal]\n                    interval = max(1, a["interval"])\n                    held = float(tile.get("yield_units", 0) or 0)\n                    if held > 0:\n                        out[day][prod] += held  # on the tile now: collected today\n                    per_cycle = max(1.0, ANIMAL_UNITS_PER_DAY[animal] * interval)  # fitted, full care\n                    bonus_day = bonus_share * (per_cycle - 1.0) / interval\n                    pending = float(tile.get("pending_care_bonus", 0) or 0)\n                    first = True\n                    for d in range(day, last_day):\n                        since = d + 1 - placed - a["first_yield_day"]  # tonight\'s production\n                        if since < 0 or since % interval:\n                            continue\n                        if first:\n                            units = 1.0 + bonus_share * pending + bonus_day * (d - day + 1)\n                            first = False\n                        else:\n                            units = 1.0 + bonus_day * interval\n                        out[d + 1][prod] += min(float(a["max_held"]), units)\n                    continue\n                start = max(day, placed + a["first_yield_day"])\n                for d in range(start, last_day + 1):\n                    out[d][ANIMAL_PRODUCT[animal]] += ANIMAL_UNITS_PER_DAY[animal]\n    for d in range(day, last_day + 1):\n        out[d]["FERTILIZER"] += FERTILIZER_SURPLUS * n_animals\n    return out\n\n\ndef sales_from_supply(supply, day, lag=None, last_day=FINAL_DAY):\n    """Production sold with a fractional one-day lag (melons the same day)."""\n    if lag is None:\n        lag = SALES_LAG\n    out = {d: {p: 0.0 for p in PRODUCTS} for d in range(day, last_day + 1)}\n    for d, units in supply.items():\n        for p, u in units.items():\n            if u <= 0:\n                continue\n            if p == "MELON" or d >= last_day:\n                out[d][p] += u\n            else:\n                out[d][p] += u * (1 - lag)\n                out[d + 1][p] += u * lag\n    return out\n\n\nclass PriceProjection:\n    """Marginal price per product per day given a consumption forecast, the opponent\'s\n    projected sales and our own planned sales (units per day)."""\n\n    def __init__(self, inventory, day, used, theirs, ours=None, last_day=FINAL_DAY, params=None):\n        self.day = day\n        self.last_day = last_day\n        self.params = params\n        self.inventory = {}  # product -> {day: inventory at the start of the day}\n        self.flow = {}  # product -> {day: net units added to the market that day}\n        self.ours = ours or {}\n        self.theirs = theirs\n        self.used = used\n        for p in PRODUCTS:\n            inv = float(inventory.get(p, 10000))\n            path = {}\n            flow = {}\n            for d in range(day, last_day + 1):\n                path[d] = inv\n                flow[d] = (\n                    self.ours.get(d, {}).get(p, 0.0)\n                    + theirs.get(d, {}).get(p, 0.0)\n                    - used.get(d, {}).get(p, 0.0)\n                )\n                inv += flow[d]\n            self.inventory[p] = path\n            self.flow[p] = flow\n\n    def price(self, product, d, extra_units=0.0):\n        """Marginal price of a unit of `product` sold on day d (noon inventory: the start\n        of the day plus half the day\'s net flow), after `extra_units` more of ours."""\n        path = self.inventory[product]\n        d = min(max(d, self.day), self.last_day)\n        mid = path[d] + 0.5 * self.flow[product][d] + extra_units\n        return market_price(product, int(round(mid)), self.params)\n\n    def sale_schedule(self, product, units, max_per_day=None):\n        """Spread `units` over the remaining days for the best total at these projected\n        prices (greedy by marginal price, self-impact included). Returns (plan, value)."""\n        units = int(units)\n        plan = {}\n        value = 0.0\n        for _ in range(units):\n            best = None\n            for d in range(self.day, self.last_day + 1):\n                if max_per_day is not None and plan.get(d, 0) >= max_per_day:\n                    continue\n                price = self.price(product, d, plan.get(d, 0))\n                if best is None or price > best[0]:\n                    best = (price, d)\n            if best is None:\n                break\n            plan[best[1]] = plan.get(best[1], 0) + 1\n            value += best[0]\n        return plan, value\n\n    def sell_now_value(self, product, units, extra_units=0.0):\n        return sum(self.price(product, self.day, extra_units + k) for k in range(int(units)))\n\n    def crop_value(self, crop, plant_day, labour_price=0.0, fertilized=False):\n        """Revenue of one tile planted on `plant_day`, at projected prices, minus seed\n        and the labour its visits cost (ops x labour_price)."""\n        data = CROPS[crop]\n        events = []\n        if data["ongoing"]:\n            first = plant_day + data["first_yield_day"]\n            for k in range(data["max_yield"]):\n                d = first + k * data["interval"]\n                if d <= self.last_day:\n                    events.append((d, 2.0 if fertilized else 1.0))\n        else:\n            d = plant_day + (data["first_yield_day"] if crop == "MELON" else data["max_yield_day"])\n            if d <= self.last_day:\n                units = data["max_yield"] if fertilized else UNITS_PER_HARVEST[crop]\n                events.append((d, units))\n        if not events:\n            return -float(data["seed"])\n        revenue = 0.0\n        for d, units in events:\n            revenue += sum(self.price(crop, d + 1, k) for k in range(int(round(units))))\n        span = max(1, events[-1][0] - plant_day + 1)\n        ops = span + len(events) + 1  # a watering a day, a harvest per event, the planting\n        return revenue - data["seed"] - labour_price * ops\n\n    def animal_value(self, animal, day, feed_price, labour_price=0.0):\n        """Revenue of one animal bought on `day` to the end, minus cost, feed and labour."""\n        a = ANIMALS[animal]\n        product = ANIMAL_PRODUCT[animal]\n        start = day + a["first_yield_day"]\n        revenue = 0.0\n        for d in range(start, self.last_day + 1):\n            units = ANIMAL_UNITS_PER_DAY[animal]\n            revenue += units * self.price(product, d)\n            revenue += 0.7 * self.price("FERTILIZER", d)\n        days = max(0, self.last_day - day + 1)\n        return revenue - a["cost"] - days * (feed_price + labour_price * 3)\n\n    def fertilizer_dose_value(self, crop, event_day):\n        """One extra unit at the next event versus selling the dose today."""\n        return self.price(crop, event_day + 1) - self.price("FERTILIZER", self.day)\n\n\n__all__ = ["PriceProjection", "supply_forecast", "sales_from_supply", "consumption_forecast"]\n'),
