    ('_athena_schedbot.econ', '"""Market arithmetic: exact price curve, shop consumption, deficit projections."""\n\nfrom _athena_farmbot.constants import MARKET_PARAMS, MAX_SHOP_INSTANCES, SHOPS, market_price\n\nI0 = 10000\nTURNS_PER_DAY = 24\nSHOP_STEPS_PER_DAY = 6  # townShopSellInterval 4 -> 6 draws per 24-step day\nTOMATO_SHOPS = ("PIZZA_SHOP", "FARMERS_MARKET")\nCARROT_SHOPS = ("PET_CAFE", "FARMERS_MARKET")\nEGG_SHOPS = ("BAKERY", "BRUNCH_SPOT")\nMILK_SHOPS = ("PIZZA_SHOP", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP")\nSTRAWBERRY_SHOPS = ("BRUNCH_SPOT", "ICE_CREAM_SHOP", "SMOOTHIE_SHOP", "FARMERS_MARKET")\n\n\ndef daily_consumption(shops):\n    """Units per day each product loses to the unlocked shops plus the town centre."""\n    rate = {item: 1 for item in MARKET_PARAMS if item != "FERTILIZER"}\n    for shop in shops:\n        products = SHOPS[shop]\n        mult = 2 if len(products) == 1 else 1\n        for item in products:\n            rate[item] = rate.get(item, 0) + mult * SHOP_STEPS_PER_DAY\n    return rate\n\n\ndef shop_count(shops, names):\n    return sum(1 for s in shops if s in names)\n\n\ndef projected_inventory(item, inventory, shops, days):\n    return inventory - daily_consumption(shops).get(item, 0) * days\n\n\ndef sale_revenue(item, inventory, units):\n    total = 0\n    for k in range(units):\n        total += market_price(item, inventory + k)\n    return total\n\n\ndef units_above(item, inventory, min_price, limit):\n    """How many units sell at or above ``min_price`` starting from ``inventory``."""\n    n = 0\n    while n < limit and market_price(item, inventory + n) >= min_price:\n        n += 1\n    return n\n\n\ndef base_price(item):\n    return MARKET_PARAMS[item]["base"]\n\n\ndef remaining_draws(shops, day):\n    """Shop draws still to come: one per third day up to day 24, eight at most."""\n    drawn = len(shops)\n    due = sum(1 for d in (3, 6, 9, 12, 15, 18, 21, 24) if d > day)\n    return max(0, min(MAX_SHOP_INSTANCES - drawn, due))\n\n\ndef expected_consumption(item, shops, day):\n    """Daily consumption today plus what the remaining draws add in expectation\n    (each draw is uniform over the eight shop types)."""\n    rate = daily_consumption(shops).get(item, 0)\n    extra = 0.0\n    for products in SHOPS.values():\n        if item in products:\n            extra += (2 if len(products) == 1 else 1) * SHOP_STEPS_PER_DAY / len(SHOPS)\n    return rate + remaining_draws(shops, day) * extra\n'),
