_AGENTS = {}


def agent(observation, configuration=None):
    try:
        player = int(observation["player"])
        step = int(observation.get("step", 0))
        inst = _AGENTS.get(player)
        if inst is None or step <= inst.last_step:
            inst = AdaptiveAgent(_ZEUS_AGENT, _PARAMS, planner="value")
            _AGENTS[player] = inst
        return inst.act(observation, configuration)
    except Exception:
        try:
            return _ZEUS_AGENT(observation, configuration)
        except Exception:
            return {"farmer": ["PASS"], "hands": [], "market": []}
